import csv
import io
import re


_NUMBER = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(io.StringIO(raw_csv, newline=""),
                              delimiter=",", quotechar='"', doublequote=True))
    expected_width = 2

    def is_numeric(value):
        return _NUMBER.fullmatch(value.strip()) is not None

    def is_label(value):
        return any(char.isalpha() for char in value) and not is_numeric(value)

    # The samples start with numeric data, so do not discard the first row
    # unless an actual text header precedes the numeric records.
    header_index = None
    previous_index = None
    for index, record in enumerate(records):
        if not any(value.strip() for value in record):
            continue
        if len(record) == expected_width and all(is_numeric(value) for value in record):
            if previous_index is not None:
                candidate = records[previous_index]
                if len(candidate) == expected_width and all(map(is_label, candidate)):
                    header_index = previous_index
            break
        previous_index = index

    columns = records.pop(header_index) if header_index is not None else []
    width = max(expected_width, len(columns), max(map(len, records), default=0))
    used = set(columns)
    for index in range(len(columns), width):
        base = f"column_{index + 1}"
        name = base
        suffix = 2
        while name in used:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used.add(name)

    return {
        "columns": columns,
        "rows": [record + [""] * (width - len(record)) for record in records],
    }
